/** Error de dominio con código estable y estado HTTP asociado. */
export class CartError extends Error {
  constructor(status, code, message) {
    super(message);
    this.name = 'CartError';
    this.status = status;
    this.code = code;
  }
}

export const invalid = (message) => new CartError(400, 'INVALID_REQUEST', message);
export const unknownSku = (sku) => new CartError(404, 'UNKNOWN_SKU', `El producto "${sku}" no existe`);
export const tooManyLines = (max) =>
  new CartError(409, 'CART_LINE_LIMIT', `El carrito no puede tener más de ${max} productos distintos`);
export const quantityExceeded = (max) =>
  new CartError(409, 'QUANTITY_LIMIT', `No se pueden añadir más de ${max} unidades de un mismo producto`);

const int = (value, fallback) => {
  if (value === undefined || value === '') return fallback;
  const n = Number(value);
  if (!Number.isInteger(n) || n <= 0) throw new Error(`Valor de configuración no válido: ${value}`);
  return n;
};

export function loadConfig(env = process.env) {
  return {
    port: int(env.PORT, 3000),
    redisUrl: env.REDIS_URL || null,
    limits: {
      maxLines: int(env.CART_MAX_LINES, 100),
      maxQuantityPerLine: int(env.CART_MAX_QTY_PER_LINE, 99),
      cartTtlSeconds: int(env.CART_TTL_SECONDS, 60 * 60 * 24 * 30),
      idempotencyTtlSeconds: int(env.IDEMPOTENCY_TTL_SECONDS, 60 * 60 * 24),
    },
  };
}

export const defaultLimits = loadConfig({}).limits;

/**
 * Catálogo de productos. El carrito solo guarda SKU y cantidad; nombre y precio
 * se resuelven aquí en cada lectura, de modo que el cliente nunca decide el precio.
 *
 * En producción se sustituye por un cliente del servicio de catálogo (con caché)
 * que implemente el mismo método `getMany`.
 */
export class InMemoryCatalog {
  /** @param {Array<{sku: string, name: string, price: number}>} products precio en céntimos */
  constructor(products, currency = 'EUR') {
    this.currency = currency;
    this.products = new Map(products.map((p) => [p.sku, p]));
  }

  /** @returns {Promise<Map<string, {sku: string, name: string, price: number}>>} */
  async getMany(skus) {
    const found = new Map();
    for (const sku of skus) {
      const product = this.products.get(sku);
      if (product) found.set(sku, product);
    }
    return found;
  }
}

export const sampleCatalog = () =>
  new InMemoryCatalog([
    { sku: 'CAM-001', name: 'Camiseta básica', price: 1299 },
    { sku: 'PAN-002', name: 'Pantalón vaquero', price: 3995 },
    { sku: 'ZAP-003', name: 'Zapatillas deportivas', price: 5990 },
    { sku: 'GOR-004', name: 'Gorra', price: 950 },
  ]);

import { quantityExceeded, tooManyLines } from '../errors.js';

/**
 * Almacén en memoria para desarrollo y tests. Mismo contrato que RedisCartStore.
 * No sirve para producción: el estado vive en un único proceso y las entradas
 * caducadas solo se liberan cuando se vuelve a acceder a ellas.
 */
export class MemoryCartStore {
  constructor(limits, now = () => Date.now()) {
    this.limits = limits;
    this.now = now;
    this.carts = new Map(); // cartId -> { items: Map<sku, qty>, expiresAt }
    this.idempotency = new Map(); // `${cartId}:${key}` -> expiresAt
  }

  #live(cartId) {
    const cart = this.carts.get(cartId);
    if (cart && cart.expiresAt <= this.now()) {
      this.carts.delete(cartId);
      return undefined;
    }
    return cart;
  }

  #touch(cartId, cart) {
    cart.expiresAt = this.now() + this.limits.cartTtlSeconds * 1000;
    this.carts.set(cartId, cart);
  }

  async getItems(cartId) {
    return Object.fromEntries(this.#live(cartId)?.items ?? []);
  }

  async addItem(cartId, sku, quantity, { idempotencyKey } = {}) {
    const idemKey = idempotencyKey && `${cartId}:${idempotencyKey}`;
    if (idemKey && this.idempotency.get(idemKey) > this.now()) return;

    const cart = this.#live(cartId) ?? { items: new Map(), expiresAt: 0 };
    const current = cart.items.get(sku);
    if (current === undefined && cart.items.size >= this.limits.maxLines) {
      throw tooManyLines(this.limits.maxLines);
    }
    const next = (current ?? 0) + quantity;
    if (next > this.limits.maxQuantityPerLine) throw quantityExceeded(this.limits.maxQuantityPerLine);

    cart.items.set(sku, next);
    this.#touch(cartId, cart);
    if (idemKey) this.idempotency.set(idemKey, this.now() + this.limits.idempotencyTtlSeconds * 1000);
  }

  async setItem(cartId, sku, quantity) {
    const cart = this.#live(cartId) ?? { items: new Map(), expiresAt: 0 };
    if (!cart.items.has(sku) && cart.items.size >= this.limits.maxLines) {
      throw tooManyLines(this.limits.maxLines);
    }
    cart.items.set(sku, quantity);
    this.#touch(cartId, cart);
  }

  async removeItem(cartId, sku) {
    const cart = this.#live(cartId);
    if (!cart) return;
    cart.items.delete(sku);
    if (cart.items.size === 0) this.carts.delete(cartId);
  }

  async clear(cartId) {
    this.carts.delete(cartId);
  }

  async ping() {}

  async close() {}
}

import { quantityExceeded, tooManyLines } from '../errors.js';

/**
 * Almacén en Redis: un hash por carrito (campo = SKU, valor = cantidad).
 *
 * - Cada mutación es un único script Lua, atómico en Redis: no hay ciclo
 *   leer-modificar-escribir en la aplicación ni bloqueos distribuidos, así que
 *   cualquier número de réplicas del servicio puede escribir en el mismo carrito.
 * - El coste de cada operación es O(1) respecto al tamaño del carrito
 *   (la lectura es O(líneas), acotado por maxLines).
 * - Las claves comparten la etiqueta {cartId}, por lo que todas las claves de un
 *   carrito caen en el mismo slot y el esquema funciona en Redis Cluster.
 * - Los carritos abandonados caducan solos (TTL renovado en cada escritura).
 */

const ADD_ITEM = `
local idem = KEYS[2]
if idem and redis.call('EXISTS', idem) == 1 then return 'OK' end
local sku, qty = ARGV[1], tonumber(ARGV[2])
local maxLines, maxQty = tonumber(ARGV[3]), tonumber(ARGV[4])
local current = tonumber(redis.call('HGET', KEYS[1], sku))
if not current and redis.call('HLEN', KEYS[1]) >= maxLines then return 'LINES' end
local total = (current or 0) + qty
if total > maxQty then return 'QTY' end
redis.call('HSET', KEYS[1], sku, total)
redis.call('EXPIRE', KEYS[1], ARGV[5])
if idem then redis.call('SET', idem, 1, 'EX', ARGV[6]) end
return 'OK'
`;

const SET_ITEM = `
local sku = ARGV[1]
if redis.call('HEXISTS', KEYS[1], sku) == 0 and redis.call('HLEN', KEYS[1]) >= tonumber(ARGV[3]) then
  return 'LINES'
end
redis.call('HSET', KEYS[1], sku, ARGV[2])
redis.call('EXPIRE', KEYS[1], ARGV[4])
return 'OK'
`;

export class RedisCartStore {
  /** @param {import('ioredis').Redis | import('ioredis').Cluster} redis */
  constructor(redis, limits) {
    this.redis = redis;
    this.limits = limits;
    redis.defineCommand('cartAddItem', { lua: ADD_ITEM });
    redis.defineCommand('cartSetItem', { numberOfKeys: 1, lua: SET_ITEM });
  }

  #itemsKey(cartId) {
    return `cart:{${cartId}}:items`;
  }

  async getItems(cartId) {
    const raw = await this.redis.hgetall(this.#itemsKey(cartId));
    const items = {};
    for (const [sku, qty] of Object.entries(raw)) items[sku] = Number(qty);
    return items;
  }

  async addItem(cartId, sku, quantity, { idempotencyKey } = {}) {
    const keys = [this.#itemsKey(cartId)];
    if (idempotencyKey) keys.push(`cart:{${cartId}}:idem:${idempotencyKey}`);
    const { maxLines, maxQuantityPerLine, cartTtlSeconds, idempotencyTtlSeconds } = this.limits;
    const result = await this.redis.cartAddItem(
      keys.length, ...keys,
      sku, quantity, maxLines, maxQuantityPerLine, cartTtlSeconds, idempotencyTtlSeconds,
    );
    this.#check(result);
  }

  async setItem(cartId, sku, quantity) {
    const result = await this.redis.cartSetItem(
      this.#itemsKey(cartId), sku, quantity, this.limits.maxLines, this.limits.cartTtlSeconds,
    );
    this.#check(result);
  }

  async removeItem(cartId, sku) {
    await this.redis.hdel(this.#itemsKey(cartId), sku);
  }

  async clear(cartId) {
    await this.redis.del(this.#itemsKey(cartId));
  }

  async ping() {
    await this.redis.ping();
  }

  async close() {
    await this.redis.quit();
  }

  #check(result) {
    if (result === 'LINES') throw tooManyLines(this.limits.maxLines);
    if (result === 'QTY') throw quantityExceeded(this.limits.maxQuantityPerLine);
  }
}

import { invalid, unknownSku } from './errors.js';

const CART_ID = /^[A-Za-z0-9_-]{1,64}$/;
const SKU = /^[A-Za-z0-9._-]{1,64}$/;
const IDEMPOTENCY_KEY = /^[A-Za-z0-9_-]{1,128}$/;

/**
 * Lógica del carrito. No guarda estado propio: todo vive en `store`, así que
 * se pueden ejecutar tantas instancias como haga falta detrás de un balanceador.
 */
export class CartService {
  constructor({ store, catalog, limits }) {
    this.store = store;
    this.catalog = catalog;
    this.limits = limits;
  }

  async getCart(cartId) {
    this.#assertCartId(cartId);
    return this.#view(cartId);
  }

  /** Suma `quantity` unidades. Con `idempotencyKey`, un reintento no vuelve a sumar. */
  async addItem(cartId, sku, quantity, { idempotencyKey } = {}) {
    this.#assertCartId(cartId);
    this.#assertQuantity(quantity);
    if (idempotencyKey !== undefined && !IDEMPOTENCY_KEY.test(idempotencyKey)) {
      throw invalid('Idempotency-Key no válida');
    }
    await this.#assertProductExists(sku);
    await this.store.addItem(cartId, sku, quantity, { idempotencyKey });
    return this.#view(cartId);
  }

  /** Fija la cantidad exacta de una línea (operación idempotente por naturaleza). */
  async setItem(cartId, sku, quantity) {
    this.#assertCartId(cartId);
    this.#assertQuantity(quantity);
    await this.#assertProductExists(sku);
    await this.store.setItem(cartId, sku, quantity);
    return this.#view(cartId);
  }

  async removeItem(cartId, sku) {
    this.#assertCartId(cartId);
    if (!SKU.test(sku)) throw invalid('SKU no válido');
    await this.store.removeItem(cartId, sku);
    return this.#view(cartId);
  }

  async clear(cartId) {
    this.#assertCartId(cartId);
    await this.store.clear(cartId);
  }

  async #view(cartId) {
    const quantities = await this.store.getItems(cartId);
    const skus = Object.keys(quantities).sort();
    const products = await this.catalog.getMany(skus);

    let subtotal = 0;
    let totalQuantity = 0;
    const items = skus.map((sku) => {
      const quantity = quantities[sku];
      const product = products.get(sku);
      // Un producto retirado del catálogo sigue viéndose, pero no suma al total.
      if (!product) return { sku, quantity, available: false };
      const lineTotal = product.price * quantity;
      subtotal += lineTotal;
      totalQuantity += quantity;
      return { sku, name: product.name, unitPrice: product.price, quantity, lineTotal, available: true };
    });

    // Importes en unidades mínimas de la moneda (céntimos) para evitar errores de coma flotante.
    return { id: cartId, items, totalQuantity, subtotal, currency: this.catalog.currency };
  }

  #assertCartId(cartId) {
    if (!CART_ID.test(cartId)) throw invalid('Identificador de carrito no válido');
  }

  #assertQuantity(quantity) {
    const max = this.limits.maxQuantityPerLine;
    if (!Number.isInteger(quantity) || quantity < 1 || quantity > max) {
      throw invalid(`"quantity" debe ser un entero entre 1 y ${max}`);
    }
  }

  async #assertProductExists(sku) {
    if (typeof sku !== 'string' || !SKU.test(sku)) throw invalid('SKU no válido');
    const found = await this.catalog.getMany([sku]);
    if (!found.has(sku)) throw unknownSku(sku);
  }
}

import { CartError, invalid } from './errors.js';

const MAX_BODY_BYTES = 10 * 1024;

const routes = [
  ['GET', /^\/healthz$/, async ({ store }) => {
    await store.ping();
    return [200, { status: 'ok' }];
  }],
  ['GET', /^\/carts\/([^/]+)$/, async ({ service }, [id]) => [200, await service.getCart(id)]],
  ['DELETE', /^\/carts\/([^/]+)$/, async ({ service }, [id]) => {
    await service.clear(id);
    return [204];
  }],
  ['POST', /^\/carts\/([^/]+)\/items$/, async ({ service }, [id], req) => {
    const { sku, quantity = 1 } = await readJson(req);
    const idempotencyKey = req.headers['idempotency-key'];
    return [200, await service.addItem(id, sku, quantity, { idempotencyKey })];
  }],
  ['PUT', /^\/carts\/([^/]+)\/items\/([^/]+)$/, async ({ service }, [id, sku], req) => {
    const { quantity } = await readJson(req);
    return [200, await service.setItem(id, sku, quantity)];
  }],
  ['DELETE', /^\/carts\/([^/]+)\/items\/([^/]+)$/, async ({ service }, [id, sku]) => [
    200,
    await service.removeItem(id, sku),
  ]],
];

/** Devuelve un manejador para `http.createServer`. */
export function createApp({ service, store, logger = console }) {
  return async (req, res) => {
    try {
      const [status, body] = await dispatch({ service, store }, req);
      send(res, status, body);
    } catch (err) {
      if (err instanceof CartError) {
        send(res, err.status, { error: { code: err.code, message: err.message } });
      } else {
        logger.error(err);
        send(res, 500, { error: { code: 'INTERNAL_ERROR', message: 'Error interno' } });
      }
    }
  };
}

async function dispatch(deps, req) {
  let path;
  try {
    path = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
  } catch {
    throw invalid('URL no válida');
  }
  for (const [method, pattern, handler] of routes) {
    const match = req.method === method && pattern.exec(path);
    if (match) return handler(deps, match.slice(1), req);
  }
  throw new CartError(404, 'NOT_FOUND', 'Ruta no encontrada');
}

async function readJson(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new CartError(413, 'PAYLOAD_TOO_LARGE', 'Cuerpo demasiado grande');
    chunks.push(chunk);
  }
  let body;
  try {
    body = JSON.parse(Buffer.concat(chunks).toString('utf8'));
  } catch {
    throw invalid('El cuerpo debe ser JSON válido');
  }
  if (body === null || typeof body !== 'object' || Array.isArray(body)) {
    throw invalid('El cuerpo debe ser un objeto JSON');
  }
  return body;
}

function send(res, status, body) {
  if (body === undefined) {
    res.writeHead(status).end();
    return;
  }
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(payload),
    'cache-control': 'no-store',
  });
  res.end(payload);
}

import http from 'node:http';
import Redis from 'ioredis';
import { createApp } from './app.js';
import { CartService } from './cartService.js';
import { sampleCatalog } from './catalog.js';
import { loadConfig } from './config.js';
import { MemoryCartStore } from './stores/memoryStore.js';
import { RedisCartStore } from './stores/redisStore.js';

const config = loadConfig();

let store;
if (config.redisUrl) {
  const redis = new Redis(config.redisUrl, { maxRetriesPerRequest: 2 });
  redis.on('error', (err) => console.error('Redis:', err.message));
  store = new RedisCartStore(redis, config.limits);
} else {
  console.warn('REDIS_URL no definida: se usa el almacén en memoria (solo para desarrollo).');
  store = new MemoryCartStore(config.limits);
}

const service = new CartService({ store, catalog: sampleCatalog(), limits: config.limits });
const server = http.createServer(createApp({ service, store }));

server.listen(config.port, () => console.log(`Carrito escuchando en el puerto ${config.port}`));

// Apagado ordenado: deja terminar las peticiones en curso antes de salir.
for (const signal of ['SIGTERM', 'SIGINT']) {
  process.once(signal, () => {
    server.close(async () => {
      await store.close();
      process.exit(0);
    });
    server.closeIdleConnections();
  });
}

// Contrato común de los almacenes. La parte de Redis solo se ejecuta si se
// define REDIS_URL (p. ej. REDIS_URL=redis://localhost:6379 npm test).
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { after, describe, test } from 'node:test';
import Redis from 'ioredis';
import { MemoryCartStore } from '../src/stores/memoryStore.js';
import { RedisCartStore } from '../src/stores/redisStore.js';

const limits = { maxLines: 3, maxQuantityPerLine: 500, cartTtlSeconds: 60, idempotencyTtlSeconds: 60 };

function contract(name, makeStore, options = {}) {
  describe(name, options, () => {
    const store = makeStore();
    after(() => store.close());
    const newId = () => randomUUID();

    test('un carrito inexistente está vacío', async () => {
      assert.deepEqual(await store.getItems(newId()), {});
    });

    test('añadir acumula cantidades', async () => {
      const id = newId();
      await store.addItem(id, 'A', 2);
      await store.addItem(id, 'A', 3);
      await store.addItem(id, 'B', 1);
      assert.deepEqual(await store.getItems(id), { A: 5, B: 1 });
    });

    test('las sumas concurrentes no pierden actualizaciones', async () => {
      const id = newId();
      await Promise.all(Array.from({ length: 200 }, () => store.addItem(id, 'A', 1)));
      assert.deepEqual(await store.getItems(id), { A: 200 });
    });

    test('la misma clave de idempotencia solo se aplica una vez', async () => {
      const id = newId();
      await Promise.all(
        Array.from({ length: 10 }, () => store.addItem(id, 'A', 2, { idempotencyKey: 'k1' })),
      );
      await store.addItem(id, 'A', 2, { idempotencyKey: 'k2' });
      assert.deepEqual(await store.getItems(id), { A: 4 });
    });

    test('una suma rechazada no consume la clave de idempotencia', async () => {
      const id = newId();
      await store.addItem(id, 'A', 499);
      await assert.rejects(store.addItem(id, 'A', 2, { idempotencyKey: 'k' }), { code: 'QUANTITY_LIMIT' });
      await store.setItem(id, 'A', 1);
      await store.addItem(id, 'A', 2, { idempotencyKey: 'k' });
      assert.deepEqual(await store.getItems(id), { A: 3 });
    });

    test('fijar, eliminar y vaciar', async () => {
      const id = newId();
      await store.addItem(id, 'A', 5);
      await store.setItem(id, 'A', 2);
      await store.setItem(id, 'B', 7);
      assert.deepEqual(await store.getItems(id), { A: 2, B: 7 });
      await store.removeItem(id, 'A');
      await store.removeItem(id, 'no-existe');
      assert.deepEqual(await store.getItems(id), { B: 7 });
      await store.clear(id);
      assert.deepEqual(await store.getItems(id), {});
    });

    test('respeta el máximo de líneas y de unidades por línea', async () => {
      const id = newId();
      await store.addItem(id, 'A', 1);
      await store.addItem(id, 'B', 1);
      await store.setItem(id, 'C', 1);
      await assert.rejects(store.addItem(id, 'D', 1), { code: 'CART_LINE_LIMIT' });
      await assert.rejects(store.setItem(id, 'D', 1), { code: 'CART_LINE_LIMIT' });
      await assert.rejects(store.addItem(id, 'A', 500), { code: 'QUANTITY_LIMIT' });
      await store.addItem(id, 'A', 499); // una línea existente sí admite más unidades
      assert.deepEqual(await store.getItems(id), { A: 500, B: 1, C: 1 });
    });
  });
}

contract('MemoryCartStore', () => new MemoryCartStore(limits));

contract('RedisCartStore', () => new RedisCartStore(new Redis(process.env.REDIS_URL), limits), {
  skip: !process.env.REDIS_URL && 'REDIS_URL no definida',
});

test('MemoryCartStore: el carrito caduca tras el TTL', async () => {
  let now = 0;
  const store = new MemoryCartStore(limits, () => now);
  await store.addItem('c', 'A', 1);
  now = 59_000;
  assert.deepEqual(await store.getItems('c'), { A: 1 });
  now = 60_000;
  assert.deepEqual(await store.getItems('c'), {});
});

test('RedisCartStore: las escrituras fijan el TTL', { skip: !process.env.REDIS_URL }, async () => {
  const redis = new Redis(process.env.REDIS_URL);
  const store = new RedisCartStore(redis, limits);
  const id = randomUUID();
  await store.addItem(id, 'A', 1, { idempotencyKey: 'k' });
  const ttl = await redis.ttl(`cart:{${id}}:items`);
  const idemTtl = await redis.ttl(`cart:{${id}}:idem:k`);
  assert.ok(ttl > 0 && ttl <= 60);
  assert.ok(idemTtl > 0 && idemTtl <= 60);
  await store.close();
});

import assert from 'node:assert/strict';
import http from 'node:http';
import { after, before, test } from 'node:test';
import { createApp } from '../src/app.js';
import { CartService } from '../src/cartService.js';
import { sampleCatalog } from '../src/catalog.js';
import { defaultLimits } from '../src/config.js';
import { MemoryCartStore } from '../src/stores/memoryStore.js';

let server;
let base;

before(async () => {
  const store = new MemoryCartStore(defaultLimits);
  const service = new CartService({ store, catalog: sampleCatalog(), limits: defaultLimits });
  server = http.createServer(createApp({ service, store, logger: { error() {} } }));
  await new Promise((resolve) => server.listen(0, resolve));
  base = `http://localhost:${server.address().port}`;
});

after(() => server.close());

async function call(method, path, body, headers = {}) {
  const res = await fetch(base + path, {
    method,
    headers: { 'content-type': 'application/json', ...headers },
    body: body === undefined ? undefined : typeof body === 'string' ? body : JSON.stringify(body),
  });
  const text = await res.text();
  return { status: res.status, body: text ? JSON.parse(text) : undefined };
}

test('flujo completo de un carrito', async () => {
  let res = await call('GET', '/carts/c1');
  assert.equal(res.status, 200);
  assert.deepEqual(res.body, { id: 'c1', items: [], totalQuantity: 0, subtotal: 0, currency: 'EUR' });

  await call('POST', '/carts/c1/items', { sku: 'CAM-001', quantity: 2 });
  await call('POST', '/carts/c1/items', { sku: 'CAM-001' }); // cantidad por defecto: 1
  res = await call('POST', '/carts/c1/items', { sku: 'GOR-004', quantity: 1 });
  assert.equal(res.status, 200);
  assert.deepEqual(res.body.items, [
    { sku: 'CAM-001', name: 'Camiseta básica', unitPrice: 1299, quantity: 3, lineTotal: 3897, available: true },
    { sku: 'GOR-004', name: 'Gorra', unitPrice: 950, quantity: 1, lineTotal: 950, available: true },
  ]);
  assert.equal(res.body.subtotal, 4847);
  assert.equal(res.body.totalQuantity, 4);

  res = await call('PUT', '/carts/c1/items/CAM-001', { quantity: 1 });
  assert.equal(res.body.subtotal, 1299 + 950);

  res = await call('DELETE', '/carts/c1/items/GOR-004');
  assert.deepEqual(res.body.items.map((i) => i.sku), ['CAM-001']);

  res = await call('DELETE', '/carts/c1');
  assert.equal(res.status, 204);
  res = await call('GET', '/carts/c1');
  assert.deepEqual(res.body.items, []);
});

test('Idempotency-Key evita duplicados en reintentos', async () => {
  const headers = { 'idempotency-key': 'abc-123' };
  await call('POST', '/carts/c2/items', { sku: 'ZAP-003', quantity: 1 }, headers);
  const res = await call('POST', '/carts/c2/items', { sku: 'ZAP-003', quantity: 1 }, headers);
  assert.equal(res.status, 200);
  assert.equal(res.body.items[0].quantity, 1);
});

test('errores de validación', async () => {
  const cases = [
    ['POST', '/carts/c3/items', { sku: 'NOPE', quantity: 1 }, 404, 'UNKNOWN_SKU'],
    ['POST', '/carts/c3/items', { sku: 'CAM-001', quantity: 0 }, 400, 'INVALID_REQUEST'],
    ['POST', '/carts/c3/items', { sku: 'CAM-001', quantity: 1.5 }, 400, 'INVALID_REQUEST'],
    ['POST', '/carts/c3/items', { sku: 'CAM-001', quantity: '2' }, 400, 'INVALID_REQUEST'],
    ['POST', '/carts/c3/items', { quantity: 1 }, 400, 'INVALID_REQUEST'],
    ['POST', '/carts/c3/items', '{mal json', 400, 'INVALID_REQUEST'],
    ['POST', '/carts/c3/items', '[]', 400, 'INVALID_REQUEST'],
    ['POST', '/carts/c3/items', { sku: 'CAM-001', pad: 'x'.repeat(11000) }, 413, 'PAYLOAD_TOO_LARGE'],
    ['PUT', '/carts/c3/items/CAM-001', {}, 400, 'INVALID_REQUEST'],
    ['PUT', '/carts/c3/items/CAM-001', { quantity: 100 }, 400, 'INVALID_REQUEST'],
    ['GET', '/carts/id%20con%20espacios', undefined, 400, 'INVALID_REQUEST'],
    ['GET', '/carts/%E0%A4%A', undefined, 400, 'INVALID_REQUEST'],
    ['GET', '/otra-cosa', undefined, 404, 'NOT_FOUND'],
  ];
  for (const [method, path, body, status, code] of cases) {
    const res = await call(method, path, body);
    assert.equal(res.status, status, `${method} ${path} ${JSON.stringify(body)?.slice(0, 60)}`);
    assert.equal(res.body.error.code, code);
  }
  assert.deepEqual((await call('GET', '/carts/c3')).body.items, []);
});

test('límite de unidades por línea', async () => {
  await call('POST', '/carts/c4/items', { sku: 'CAM-001', quantity: 99 });
  const res = await call('POST', '/carts/c4/items', { sku: 'CAM-001', quantity: 1 });
  assert.equal(res.status, 409);
  assert.equal(res.body.error.code, 'QUANTITY_LIMIT');
});

test('healthz', async () => {
  assert.deepEqual((await call('GET', '/healthz')).body, { status: 'ok' });
});
